1	package darksafe
2	
3	import (
4		"os"
5		"path/filepath"
6		"reflect"
7		"strings"
8		"testing"
9	)
10	
11	// badUTF8 is an isolated byte that is not valid UTF-8 anywhere in a string.
12	const badUTF8 = "\xff"
13	
14	// parseTextErr parses data and returns the error; it fails the test if the
15	// corrupt-text document is accepted.
16	func parseTextErr(t *testing.T, data string) error {
17		t.Helper()
18		in, err := ParseReleaseInput([]byte(data))
19		if err == nil {
20			t.Fatalf("expected corrupt-text rejection for %q", data)
21		}
22		if !reflect.DeepEqual(in, ReleasePlanInput{}) {
23			t.Fatalf("corrupt text must yield the zero config, got %+v", in)
24		}
25		return err
26	}
27	
28	// TestParse_InvalidUTF8RejectedEverywhere feeds one invalid UTF-8 byte
29	// through every string position of the configuration — application info,
30	// cluster identity, tags, conditions, spreadBy, and objects nested inside
31	// unknown extra fields — including a disabled cluster and a cluster that
32	// include/exclude rules would filter out. Every position must reject the
33	// whole document, naming the field or array item.
34	func TestParse_InvalidUTF8RejectedEverywhere(t *testing.T) {
35		base := `"app":"a","revision":"r","image":"i","batchSize":1`
36		cases := []struct {
37			name     string
38			body     string // JSON body without outer braces
39			wantPath string
40		}{
41			{"app", `"app":"a` + badUTF8 + `","revision":"r","image":"i","batchSize":1,"clusters":[]`, "$.app"},
42			{"revision", `"app":"a","revision":"` + badUTF8 + `","image":"i","batchSize":1,"clusters":[]`, "$.revision"},
43			{"image", `"app":"a","revision":"r","image":"img` + badUTF8 + `","batchSize":1,"clusters":[]`, "$.image"},
44			{"spreadBy", base + `,"clusters":[],"spreadBy":"zone` + badUTF8 + `"`, "$.spreadBy"},
45			{"cluster id", base + `,"clusters":[{"id":"c` + badUTF8 + `"}]`, "$.clusters[0].id"},
46			{"second cluster id", base + `,"clusters":[{"id":"a"},{"id":"` + badUTF8 + `"}]`, "$.clusters[1].id"},
47			{"disabled cluster id", base + `,"clusters":[{"id":"x` + badUTF8 + `","disabled":true}]`, "$.clusters[0].id"},
48			{"filtered-out cluster tag", base + `,"clusters":[{"id":"x","tags":{"env":"pr` + badUTF8 + `d"}}],"exclude":[{"env":"pr�d"}]`, "$.clusters[0].tags.env"},
49			{"tag value", base + `,"clusters":[{"id":"x","tags":{"env":"` + badUTF8 + `"}}]`, "$.clusters[0].tags.env"},
50			{"include condition value", base + `,"clusters":[],"include":[{"env":"p` + badUTF8 + `"}]`, "$.include[0].env"},
51			{"exclude condition value", base + `,"clusters":[],"exclude":[{"region":"` + badUTF8 + `"}]`, "$.exclude[0].region"},
52			{"unknown field value", base + `,"clusters":[],"meta":"` + badUTF8 + `"`, "$.meta"},
53			{"unknown nested object", base + `,"clusters":[],"meta":{"note":"` + badUTF8 + `"}`, "$.meta.note"},
54			{"unknown nested array item", base + `,"clusters":[],"items":["ok","` + badUTF8 + `"]`, "$.items[1]"},
55			{"unknown deep nesting", base + `,"clusters":[],"a":{"b":[{"c":"` + badUTF8 + `"}]}`, "$.a.b[0].c"},
56		}
57		for _, tc := range cases {
58			t.Run(tc.name, func(t *testing.T) {
59				err := parseTextErr(t, "{"+tc.body+"}")
60				msg := err.Error()
61				if !strings.Contains(msg, "UTF-8") {
62					t.Fatalf("error %q should identify invalid UTF-8", msg)
63				}
64				if strings.Contains(msg, "未配对") {
65					t.Fatalf("error %q should not blame Unicode escapes", msg)
66				}
67				if !strings.Contains(msg, tc.wantPath) {
68					t.Fatalf("error %q does not contain path %q", msg, tc.wantPath)
